example:
type Key = | Id(n: Int) | Name(n: String)

fn show(k: Key) -> String {
    match k {
        Id(n) | Name(n) => "key"    // ✗ `n` is an `Int` and a `String`
    }
}

fn show(k: Key) -> String {
    match k {
        Id(n) => "id"               // ✓ one arm each
        Name(n) => n
    }
}
